    const removeVariants=[...editorState.originalVariantIds].filter(id=>!keptVariants.has(id));if(removeVariants.length){const {error}=await sb.from('product_variants').delete().in('id',removeVariants);if(error)throw error}if(flags.color){const removeColors=[...editorState.originalColorIds].filter(id=>!keptColors.has(id));if(removeColors.length){const {error}=await sb.from('product_colors').delete().in('id',removeColors);if(error)throw error}}
